import{z as i,x as l,o as n,c as d,q as t,j as A,D as e,d as B,s,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"信号构建：从直觉到可计算量","description":"","frontmatter":{"title":"信号构建：从直觉到可计算量","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/signal-construction-sandbox.md","filePath":"quant/signal-construction-sandbox.md","lastUpdated":1791063341000}'),F={name:"quant/signal-construction-sandbox.md"};function p(C,E,h,u,D,m){const r=l("Mermaid");return n(),d("div",null,[E[2]||(E[2]=t('<h1 id="信号构建-从直觉到可计算量" tabindex="-1">信号构建：从直觉到可计算量 <a class="header-anchor" href="#信号构建-从直觉到可计算量" aria-label="Permalink to &quot;信号构建：从直觉到可计算量&quot;">​</a></h1><div class="epigraph"><p>一个直觉只有在你能写出它的相反情形时，才值得变成一行代码。</p><footer>—— 据 Jegadeesh and Titman (1993) 的动量设计与 Sloan (1996) 的应计构造口径整理</footer></div><p><a href="/quant/data-acquisition-audit">上一课</a>用五项审计把原始数据收拾成两枚时间戳齐全、宇宙完整的分析面板。本课把立项时那句经济直觉翻译成一个可计算的量：先定义式，再变换，再中性化，最后在沙盒里做单变量健康检查——健康检查不碰收益，只看信号自己。截面变换与中性化的工具在<a href="/quant/cs-rank-features">特征：滞后、截面 rank</a>、<a href="/quant/industry-neutral">行业中性</a>诸课备好，本课各用一次。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直觉到定义式是错得最多的一跳。「盈利质量差的公司未来收益低」听起来完整，落到代码里立刻分裂成十几个版本：应计用总资产还是收入标准化（<a href="/quant/accruals-anomaly">应计异常</a>）？预期盈利用季节随机游走还是分析师一致预期？极端值截不截？行业要不要剔？每个版本都是一个假说，而不是同一假说的实现。区别在于：这些选择是否在注册文档里被声明（上一课的合同），以及每个选择是否改变了你度量的对象（本课的问题）。变换不是中性装饰：rank 扔掉幅度信息，z-score 被极端值牵着走，中性化直接改写问题——「盈利意外」与「剔除行业动量后的盈利意外」是两个假设。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四步，每步一个工件。<strong>定义式</strong>：写出方向与分母。本单元案例取 \\(SUE_{i,q}=\\left(E_{i,q}-E^{\\mathrm{exp}}_{i,q}\\right)/\\sigma_i\\)，预期项用季节随机游走带漂移，标准差只用可得历史——时点纪律从定义式就开始。<strong>变换</strong>：重尾财务量先缩尾再截面 rank 或 z-score；rank 对重尾与单位选择稳健，代价是扔掉幅度。选哪个取决于假设需要次序还是幅度，不是哪个 IC 高。<strong>中性化</strong>：行业与市值中性，或在 <a href="/quant/fama-macbeth">Fama-MacBeth 回归</a>里把已知因子作控制变量；中性化是问题的一部分，必须在注册文档里，不是评估阶段的旋钮。<strong>沙盒健康检查</strong>：不碰收益，只看五样——随时间的覆盖率曲线、截面离散度、信号自相关（它预示换手）、与市值和行业的秩相关、上下半样本的符号稳定性。检查不过，回到定义式，不许直接去翻收益。</p><p><span class="marginnote">SUE（标准化盈利意外）就是用「实际盈余减去预期盈余，再除以这只股票自己的历史盈余波动」的手段来回答「这次惊喜有多大」。除以波动是为了横向可比：盈余多出 1 亿元，对市值百亿的公司是家常便饭，对市值五亿的公司就是大事件。</span></p><p><span class="marginnote">Jegadeesh 与 Titman 的动量取「过去 12 个月、跳过最近 1 个月」：跳过的那一段是买卖价差弹跳造成的短期反转，不属于动量假设。信号定义里的每一项都要能说出是为什么——哪一项是在给微观结构噪声让路。</span></p><p><span class="marginnote">缩尾（winsorize）就是把极端值拉回分位点：比如把低于 1% 分位、高于 99% 分位的信号值分别改成分位点上的取值。盈余意外这类重尾财务量里，一家公司的一次并购可以让它的取值是其余股票的几十倍；不缩尾就做 z-score，均值和标准差全被这一只票拽偏，整张截面的分数跟着失真。</span></p><h3 id="健康检查清单的位置" tabindex="-1">健康检查清单的位置 <a class="header-anchor" href="#健康检查清单的位置" aria-label="Permalink to &quot;健康检查清单的位置&quot;">​</a></h3>',11)),(n(),A(o,null,{default:e(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E7%BB%8F%E6%B5%8E%E7%9B%B4%E8%A7%89%22%5D%20--%3E%20DEF%5B%22%E5%AE%9A%E4%B9%89%E5%BC%8F%EF%BC%9A%E6%96%B9%E5%90%91%20%2B%20%E5%88%86%E6%AF%8D%EF%BC%88%E6%97%B6%E7%82%B9%E5%AE%89%E5%85%A8%EF%BC%89%22%5D%0A%20%20DEF%20--%3E%20TF%5B%22%E5%8F%98%E6%8D%A2%EF%BC%9A%E7%BC%A9%E5%B0%BE%20%2F%20%E6%88%AA%E9%9D%A2%20rank%20%2F%20z-score%22%5D%0A%20%20TF%20--%3E%20NEU%5B%22%E4%B8%AD%E6%80%A7%E5%8C%96%EF%BC%9A%E8%A1%8C%E4%B8%9A%20%2F%20%E5%B8%82%E5%80%BC%20%2F%20%E6%8E%A7%E5%88%B6%E5%8F%98%E9%87%8F%22%5D%0A%20%20NEU%20--%3E%20CHK%7B%22%E5%81%A5%E5%BA%B7%E6%A3%80%E6%9F%A5%EF%BC%9A%E8%A6%86%E7%9B%96%20%2F%20%E7%A6%BB%E6%95%A3%20%2F%20%E8%87%AA%E7%9B%B8%E5%85%B3%20%2F%20%E7%9B%B8%E5%85%B3%E7%BB%93%E6%9E%84%20%2F%20%E7%AC%A6%E5%8F%B7%E7%A8%B3%E5%AE%9A%22%7D%0A%20%20CHK%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20DEF%0A%20%20CHK%20--%3E%7C%E8%BF%87%7C%20NEXT%5B%22%E8%BF%9B%E5%85%A5%E5%8D%95%E4%BF%A1%E5%8F%B7%E8%AF%84%E4%BC%B0%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"rank 变换可以类比成比赛只记名次不记成绩：冠军领先 0.01 秒还是 10 秒，榜单上一视同仁。极端值因此伤不到排名，代价是「赢了多少」的幅度信息被扔掉——z-score 正好相反，保留幅度但会被极端值牵着走，所以才要先缩尾。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[B("健康检查为什么能不碰收益就拦住大半错误：覆盖断崖说明定义式在某个时代不可计算（分母不稳或审计漏项）；截面离散度塌缩说明信号在大多数股票上没有区分度，IC 的分母会吃掉一切；自相关的过高过低直接圈定换手与持有期的可行域；与已知因子的秩相关揭示「新信号」是不是市值或动量的马甲；上下半样本符号翻转是最便宜的可证伪性预演——注册文档里的拒绝条件在这里先小规模兑现一次。方向与符号约定在代码里一次性冻结（"),a("a",{href:"/quant/xalpha-hypothesis-code"},"XAlpha：假设到代码"),B("的口径）：多空写反是沙盒里最便宜也最贵的事故——便宜因为查得出，贵因为查不出时它伪装成反向 alpha。")],-1)),(n(),A(o,null,{default:e(()=>[s(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%A6%86%E7%9B%96%E7%8E%87%E6%96%AD%E5%B4%96%22%5D%20--%3E%20B%5B%22%E5%AE%9A%E4%B9%89%E5%BC%8F%E5%9C%A8%E6%9F%90%E4%B8%AA%E6%97%B6%E4%BB%A3%E4%B8%8D%E5%8F%AF%E8%AE%A1%E7%AE%97%3Cbr%2F%3E%E5%9B%9E%E5%8E%BB%E4%BF%AE%E5%88%86%E6%AF%8D%E4%B8%8E%E6%95%B0%E6%8D%AE%22%5D%0A%20%20C%5B%22%E7%A6%BB%E6%95%A3%E5%BA%A6%E5%A1%8C%E7%BC%A9%22%5D%20--%3E%20B%0A%20%20D%5B%22%E8%87%AA%E7%9B%B8%E5%85%B3%E8%BF%87%E9%AB%98%E6%88%96%E8%BF%87%E4%BD%8E%22%5D%20--%3E%20E%5B%22%E5%9C%88%E5%AE%9A%E6%8D%A2%E6%89%8B%E4%B8%8E%E6%8C%81%E6%9C%89%E6%9C%9F%E5%8F%AF%E8%A1%8C%E5%9F%9F%3Cbr%2F%3E%E6%8D%AE%E6%AD%A4%E5%AE%9A%E8%B0%83%E4%BB%93%E9%A2%91%E7%8E%87%22%5D%0A%20%20F%5B%22%E4%B8%8E%E5%B8%82%E5%80%BC%E3%80%81%E5%8A%A8%E9%87%8F%E7%9A%84%E7%A7%A9%E7%9B%B8%E5%85%B3%E9%AB%98%22%5D%20--%3E%20G%5B%22%E6%96%B0%E4%BF%A1%E5%8F%B7%E6%98%AF%E6%97%A7%E5%9B%A0%E5%AD%90%E7%9A%84%E9%A9%AC%E7%94%B2%3Cbr%2F%3E%E5%9B%9E%E5%8E%BB%E5%8A%A0%E4%B8%AD%E6%80%A7%E5%8C%96%22%5D%0A%20%20H%5B%22%E4%B8%8A%E4%B8%8B%E5%8D%8A%E6%A0%B7%E6%9C%AC%E7%AC%A6%E5%8F%B7%E7%BF%BB%E8%BD%AC%22%5D%20--%3E%20I%5B%22%E6%96%B9%E5%90%91%E4%B8%8D%E7%A8%B3%3Cbr%2F%3E%E5%86%99%E8%BF%9B%E6%B3%A8%E5%86%8C%E6%96%87%E6%A1%A3%E7%9A%84%E6%8B%92%E7%BB%9D%E6%9D%A1%E4%BB%B6%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">IC（信息系数）衡量信号好坏：拿「信号今天给股票排的名次」和「下期收益的实际名次」算相关系数，越接近 1 越准。「分母吃掉一切」的意思是：若信号在大多数股票上取值几乎相同，名次基本靠抽签，IC 无论正负都只是噪声——离散度检查就是在提前排掉这种情况。</span></p><p><span class="marginnote">自相关可以理解成「信号本月的取值和它上月取值的相似程度」。初学者容易以为换手率是下单以后才考虑的事——实际上定义式和变换一旦定下，信号翻新的速度就定了：自相关 0.9 的信号一个月几乎不变，可以低频调仓；自相关接近 0 的信号每周都在重排名次，交易成本会跟着换手一起爆炸。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>沙盒纪律是单变量的：交互项与机器学习组合属于后面的建模课，<a href="/quant/regularized-linear-alpha">正则线性模型</a>一类方法不改变本课义务——每个输入仍要过同样的定义式与检查。变换与中性化的每一步选择都要回注册文档对账：沙盒里顺手多试的每种变体都是一次试验，计入 N。最后，健康检查全绿不等于信号有效，它只说明这个量「可以进入评估」；值不值钱由评估课的 IC、换手与成本会师回答。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>直觉到定义式是最大的自由度跳变：方向、分母、预期模型都要在注册里声明。</li><li>变换与中性化改变度量的对象，是假设的一部分，不是评估阶段的旋钮。</li><li>沙盒健康检查不碰收益：覆盖、离散、自相关、相关结构、符号稳定。</li><li>每个未注册的变体计一次试验；符号约定在代码里冻结。</li><li>出处：Jegadeesh and Titman (1993) 的跳月设计动机；Sloan (1996) 的应计构造；截面变换见站内 rank 与中性化诸课。</li></ul>',6))])}const g=i(F,[["render",p]]);export{f as __pageData,g as default};
